/**
 * An object of this type can be returned on every function call, in case of an error
 * @param code Error code; subject to future changes. If the error code is 406, the error message must not be processed in any way and must not be displayed to the user
 * @param message Error message; subject to future changes
 */
@Serializable
data class Error(
    @SerialName("code") val code: Int,
    @SerialName("message") val message: String? = null,
    @SerialName("@type") val tdType: String = "error"
) : TdObject

/**
 * An object of this type is returned on a successful function call for certain functions
 */
@Serializable
class Ok(
    @SerialName("@type") val tdType: String = "ok"
) : TdObject

/**
 * A digit-only authentication code is delivered via a private Telegram message, which can be viewed from another active session
 * @param length Length of the code
 */
@Serializable
data class AuthenticationCodeTypeTelegramMessage(
    @SerialName("length") val length: Int,
    @SerialName("@type") val tdType: String = "authenticationCodeTypeTelegramMessage"
) : AuthenticationCodeType

/**
 * A digit-only authentication code is delivered via an SMS message to the specified phone number; non-official applications may not receive this type of code
 * @param length Length of the code
 */
@Serializable
data class AuthenticationCodeTypeSms(
    @SerialName("length") val length: Int,
    @SerialName("@type") val tdType: String = "authenticationCodeTypeSms"
) : AuthenticationCodeType

/**
 * An authentication code is a word delivered via an SMS message to the specified phone number; non-official applications may not receive this type of code
 * @param firstLetter The first letters of the word if known
 */
@Serializable
data class AuthenticationCodeTypeSmsWord(
    @SerialName("first_letter") val firstLetter: String? = null,
    @SerialName("@type") val tdType: String = "authenticationCodeTypeSmsWord"
) : AuthenticationCodeType

/**
 * An authentication code is a phrase from multiple words delivered via an SMS message to the specified phone number; non-official applications may not receive this type of code
 * @param firstWord The first word of the phrase if known
 */
@Serializable
data class AuthenticationCodeTypeSmsPhrase(
    @SerialName("first_word") val firstWord: String? = null,
    @SerialName("@type") val tdType: String = "authenticationCodeTypeSmsPhrase"
) : AuthenticationCodeType

/**
 * A digit-only authentication code is delivered via a phone call to the specified phone number
 * @param length Length of the code
 */
@Serializable
data class AuthenticationCodeTypeCall(
    @SerialName("length") val length: Int,
    @SerialName("@type") val tdType: String = "authenticationCodeTypeCall"
) : AuthenticationCodeType

/**
 * An authentication code is delivered by an immediately canceled call to the specified phone number. The phone number that calls is the code that must be entered automatically
 * @param pattern Pattern of the phone number from which the call will be made
 */
@Serializable
data class AuthenticationCodeTypeFlashCall(
    @SerialName("pattern") val pattern: String? = null,
    @SerialName("@type") val tdType: String = "authenticationCodeTypeFlashCall"
) : AuthenticationCodeType

/**
 * An authentication code is delivered by an immediately canceled call to the specified phone number. The last digits of the phone number that calls are the code that must be entered manually by the user
 * @param phoneNumberPrefix Prefix of the phone number from which the call will be made
 * @param length Number of digits in the code, excluding the prefix
 */
@Serializable
data class AuthenticationCodeTypeMissedCall(
    @SerialName("phone_number_prefix") val phoneNumberPrefix: String? = null,
    @SerialName("length") val length: Int,
    @SerialName("@type") val tdType: String = "authenticationCodeTypeMissedCall"
) : AuthenticationCodeType

/**
 * A digit-only authentication code is delivered to https://fragment.com. The user must be logged in there via a wallet owning the phone number's NFT
 * @param url URL to open to receive the code
 * @param length Length of the code
 */
@Serializable
data class AuthenticationCodeTypeFragment(
    @SerialName("url") val url: String? = null,
    @SerialName("length") val length: Int,
    @SerialName("@type") val tdType: String = "authenticationCodeTypeFragment"
) : AuthenticationCodeType

/**
 * A digit-only authentication code is delivered via Firebase Authentication to the official Android application
 * @param deviceVerificationParameters Parameters to be used for device verification
 * @param length Length of the code
 */
@Serializable
data class AuthenticationCodeTypeFirebaseAndroid(
    @SerialName("device_verification_parameters") val deviceVerificationParameters: FirebaseDeviceVerificationParameters? = null,
    @SerialName("length") val length: Int,
    @SerialName("@type") val tdType: String = "authenticationCodeTypeFirebaseAndroid"
) : AuthenticationCodeType

/**
 * A digit-only authentication code is delivered via Firebase Authentication to the official iOS application
 * @param receipt Receipt of successful application token validation to compare with receipt from push notification
 * @param pushTimeout Time after the next authentication method is expected to be used if verification push notification isn't received, in seconds
 * @param length Length of the code
 */
@Serializable
data class AuthenticationCodeTypeFirebaseIos(
    @SerialName("receipt") val receipt: String? = null,
    @SerialName("push_timeout") val pushTimeout: Int,
    @SerialName("length") val length: Int,
    @SerialName("@type") val tdType: String = "authenticationCodeTypeFirebaseIos"
) : AuthenticationCodeType

/**
 * Information about the authentication code that was sent
 * @param phoneNumber A phone number that is being authenticated
 * @param type The way the code was sent to the user
 * @param nextType The way the next code will be sent to the user; may be null
 * @param timeout Timeout before the code can be re-sent, in seconds
 */
@Serializable
data class AuthenticationCodeInfo(
    @SerialName("phone_number") val phoneNumber: String? = null,
    @SerialName("type") val type: AuthenticationCodeType? = null,
    @SerialName("next_type") val nextType: AuthenticationCodeType? = null,
    @SerialName("timeout") val timeout: Int,
    @SerialName("@type") val tdType: String = "authenticationCodeInfo"
) : TdObject

/**
