/**
 * Describes a location on planet Earth
 * @param latitude Latitude of the location in degrees; as defined by the sender
 * @param longitude Longitude of the location, in degrees; as defined by the sender
 * @param horizontalAccuracy The estimated horizontal accuracy of the location, in meters; as defined by the sender. 0 if unknown
 */
@Serializable
data class Location(
    @SerialName("latitude") val latitude: Double,
    @SerialName("longitude") val longitude: Double,
    @SerialName("horizontal_accuracy") val horizontalAccuracy: Double,
    @SerialName("@type") val tdType: String = "location"
) : TdObject

/**
 * A live location
 * @param location The current location
 * @param livePeriod Time relative to the message send date, for which the location can be updated, in seconds; if 0x7FFFFFFF, then location can be updated forever
 * @param heading The direction in which the location moves, in degrees; 1-360; 0 if unknown
 * @param proximityAlertRadius The maximum distance to another chat member for proximity alerts, in meters (0-100000). 0 if the notification is disabled. Can't be enabled in direct messages chats, channels and Saved Messages. Available only to the message sender
 */
@Serializable
data class LiveLocation(
    @SerialName("location") val location: Location? = null,
    @SerialName("live_period") val livePeriod: Int,
    @SerialName("heading") val heading: Int,
    @SerialName("proximity_alert_radius") val proximityAlertRadius: Int,
    @SerialName("@type") val tdType: String = "liveLocation"
) : TdObject

/**
 * Describes a venue
 * @param location Venue location; as defined by the sender
 * @param title Venue name; as defined by the sender
 * @param address Venue address; as defined by the sender
 * @param provider Provider of the venue database; as defined by the sender. Currently, only "foursquare" and "gplaces" (Google Places) need to be supported
 * @param id Identifier of the venue in the provider database; as defined by the sender
 * @param type Type of the venue in the provider database; as defined by the sender
 */
@Serializable
data class Venue(
    @SerialName("location") val location: Location? = null,
    @SerialName("title") val title: String? = null,
    @SerialName("address") val address: String? = null,
    @SerialName("provider") val provider: String? = null,
    @SerialName("id") val id: String? = null,
    @SerialName("type") val type: String? = null,
    @SerialName("@type") val tdType: String = "venue"
) : TdObject

/**
 * Describes a game. Use getInternalLink with internalLinkTypeGame to share the game
 * @param id Unique game identifier
 * @param shortName Game short name
 * @param title Game title
 * @param text Game text, usually containing scoreboards for a game
 * @param photo Game photo
 * @param animation Game animation; may be null
 */
@Serializable
data class Game(
    @SerialName("id") val id: Long,
    @SerialName("short_name") val shortName: String? = null,
    @SerialName("title") val title: String? = null,
    @SerialName("text") val text: FormattedText? = null,
    @SerialName("description") val description: String? = null,
    @SerialName("photo") val photo: Photo? = null,
    @SerialName("animation") val animation: Animation? = null,
    @SerialName("@type") val tdType: String = "game"
) : TdObject

/**
 * Describes state of the stake dice
 * @param stateHash Hash of the state to use for sending the next dice; may be empty if the stake dice can't be sent by the current user
 * @param stakeToncoinAmount The Toncoin amount that was staked in the previous roll; in the smallest units of the currency
 * @param suggestedStakeToncoinAmounts The amounts of Toncoins that are suggested to be staked; in the smallest units of the currency
 * @param currentStreak The number of rolled sixes towards the streak; 0-2
 * @param prizePerMille The number of Toncoins received by the user for each 1000 Toncoins staked if the dice outcome is 1-6 correspondingly; may be empty if the stake dice can't be sent by the current user
 * @param streakPrizePerMille The number of Toncoins received by the user for each 1000 Toncoins staked if the dice outcome is 6 three times in a row with the same stake
 */
@Serializable
data class StakeDiceState(
    @SerialName("state_hash") val stateHash: String? = null,
    @SerialName("stake_toncoin_amount") val stakeToncoinAmount: Long,
    @SerialName("suggested_stake_toncoin_amounts") val suggestedStakeToncoinAmounts: List<Long>? = null,
    @SerialName("current_streak") val currentStreak: Int,
    @SerialName("prize_per_mille") val prizePerMille: List<Int>? = null,
    @SerialName("streak_prize_per_mille") val streakPrizePerMille: Int,
    @SerialName("@type") val tdType: String = "stakeDiceState"
) : TdObject

/**
 * Describes a Web App. Use getInternalLink with internalLinkTypeWebApp to share the Web App
 * @param shortName Web App short name
 * @param title Web App title
 * @param photo Web App photo
 * @param animation Web App animation; may be null
 */
@Serializable
data class WebApp(
    @SerialName("short_name") val shortName: String? = null,
    @SerialName("title") val title: String? = null,
    @SerialName("description") val description: String? = null,
    @SerialName("photo") val photo: Photo? = null,
    @SerialName("animation") val animation: Animation? = null,
    @SerialName("@type") val tdType: String = "webApp"
) : TdObject

/**
 * Describes a poll
 * @param id Unique poll identifier
 * @param question Poll question; 1-300 characters; may contain only custom emoji entities
 * @param options List of poll answer options
 * @param totalVoterCount Total number of voters, participating in the poll
 * @param recentVoterIds Identifiers of recent voters, if the poll is non-anonymous and poll results are available
 * @param canGetVoters True, if the current user can get voters in the poll using getPollVoters
 * @param canSeeResults True, if the current user can see results of the poll
 * @param isAnonymous True, if the poll is anonymous
 * @param allowsMultipleAnswers True, if multiple answer options can be chosen simultaneously
 * @param allowsRevoting True, if the poll can be answered multiple times
 * @param membersOnly True, if only the users that are members of the chat for more than a day will be able to vote
 * @param countryCodes The list of two-letter ISO 3166-1 alpha-2 codes of countries, users from which will be able to vote. If empty, then all users can participate in the poll
 * @param optionOrder The list of 0-based poll identifiers in which the options of the poll must be shown; empty if the order of options must not be changed
 * @param type Type of the poll
 * @param openPeriod Amount of time the poll will be active after creation, in seconds
 * @param closeDate Point in time (Unix timestamp) when the poll will automatically be closed
 * @param isClosed True, if the poll is closed
 * @param voteRestrictionReason The reason describing, why the current user can't vote in the poll; may be null if the user can vote in the poll
 */
@Serializable
data class Poll(
    @SerialName("id") val id: Long,
    @SerialName("question") val question: FormattedText? = null,
    @SerialName("options") val options: List<PollOption>? = null,
    @SerialName("total_voter_count") val totalVoterCount: Int,
    @SerialName("recent_voter_ids") val recentVoterIds: List<MessageSender>? = null,
    @SerialName("can_get_voters") val canGetVoters: Boolean,
    @SerialName("can_see_results") val canSeeResults: Boolean,
    @SerialName("is_anonymous") val isAnonymous: Boolean,
    @SerialName("allows_multiple_answers") val allowsMultipleAnswers: Boolean,
    @SerialName("allows_revoting") val allowsRevoting: Boolean,
    @SerialName("members_only") val membersOnly: Boolean,
    @SerialName("country_codes") val countryCodes: List<String>? = null,
    @SerialName("option_order") val optionOrder: List<Int>? = null,
    @SerialName("type") val type: PollType? = null,
    @SerialName("open_period") val openPeriod: Int,
    @SerialName("close_date") val closeDate: Int,
    @SerialName("is_closed") val isClosed: Boolean,
    @SerialName("vote_restriction_reason") val voteRestrictionReason: PollVoteRestrictionReason? = null,
    @SerialName("@type") val tdType: String = "poll"
) : TdObject

/**
