/**
 * Describes rights of a business bot
 * @param canReply True, if the bot can send and edit messages in the private chats that had incoming messages in the last 24 hours
 * @param canReadMessages True, if the bot can mark incoming private messages as read
 * @param canDeleteSentMessages True, if the bot can delete sent messages
 * @param canDeleteAllMessages True, if the bot can delete any message
 * @param canEditName True, if the bot can edit name of the business account
 * @param canEditBio True, if the bot can edit bio of the business account
 * @param canEditProfilePhoto True, if the bot can edit profile photo of the business account
 * @param canEditUsername True, if the bot can edit username of the business account
 * @param canViewGiftsAndStars True, if the bot can view gifts and Telegram Star amount owned by the business account
 * @param canSellGifts True, if the bot can sell regular gifts received by the business account
 * @param canChangeGiftSettings True, if the bot can change gift receiving settings of the business account
 * @param canTransferAndUpgradeGifts True, if the bot can transfer and upgrade gifts received by the business account
 * @param canTransferStars True, if the bot can transfer Telegram Stars received by the business account to account of the bot, or use them to upgrade and transfer gifts
 * @param canManageStories True, if the bot can post, edit and delete stories
 */
@Serializable
data class BusinessBotRights(
    @SerialName("can_reply") val canReply: Boolean,
    @SerialName("can_read_messages") val canReadMessages: Boolean,
    @SerialName("can_delete_sent_messages") val canDeleteSentMessages: Boolean,
    @SerialName("can_delete_all_messages") val canDeleteAllMessages: Boolean,
    @SerialName("can_edit_name") val canEditName: Boolean,
    @SerialName("can_edit_bio") val canEditBio: Boolean,
    @SerialName("can_edit_profile_photo") val canEditProfilePhoto: Boolean,
    @SerialName("can_edit_username") val canEditUsername: Boolean,
    @SerialName("can_view_gifts_and_stars") val canViewGiftsAndStars: Boolean,
    @SerialName("can_sell_gifts") val canSellGifts: Boolean,
    @SerialName("can_change_gift_settings") val canChangeGiftSettings: Boolean,
    @SerialName("can_transfer_and_upgrade_gifts") val canTransferAndUpgradeGifts: Boolean,
    @SerialName("can_transfer_stars") val canTransferStars: Boolean,
    @SerialName("can_manage_stories") val canManageStories: Boolean,
    @SerialName("@type") val tdType: String = "businessBotRights"
) : TdObject

/**
 * Describes a business bot connected to an account
 * @param botUserId User identifier of the bot
 * @param recipients Private chats that will be accessible to the bot
 * @param rights Rights of the bot
 */
@Serializable
data class BusinessConnectedBot(
    @SerialName("bot_user_id") val botUserId: Long,
    @SerialName("recipients") val recipients: BusinessRecipients? = null,
    @SerialName("rights") val rights: BusinessBotRights? = null,
    @SerialName("@type") val tdType: String = "businessConnectedBot"
) : TdObject

/**
 * Describes a connection of a bot to an account
 * @param bot Information about the bot
 * @param connectionDate Point in time (Unix timestamp) when the bot was added; may be 0 if unknown
 * @param deviceModel Model of the device that was used for the bot connection, as provided by the application; may be empty if unknown
 * @param location A human-readable description of the location from which the bot was connected, based on the IP address; may be empty if unknown
 */
@Serializable
data class BusinessConnectedBotInfo(
    @SerialName("bot") val bot: BusinessConnectedBot? = null,
    @SerialName("connection_date") val connectionDate: Int,
    @SerialName("device_model") val deviceModel: String? = null,
    @SerialName("location") val location: String? = null,
    @SerialName("@type") val tdType: String = "businessConnectedBotInfo"
) : TdObject

/**
 * Describes settings for a business account start page
 * @param title Title text of the start page
 * @param message Message text of the start page
