data class Gift(
    @SerialName("id") val id: Long,
    @SerialName("publisher_chat_id") val publisherChatId: Long,
    @SerialName("sticker") val sticker: Sticker? = null,
    @SerialName("star_count") val starCount: Long,
    @SerialName("default_sell_star_count") val defaultSellStarCount: Long,
    @SerialName("upgrade_star_count") val upgradeStarCount: Long,
    @SerialName("upgrade_variant_count") val upgradeVariantCount: Int,
    @SerialName("has_colors") val hasColors: Boolean,
    @SerialName("is_for_birthday") val isForBirthday: Boolean,
    @SerialName("is_premium") val isPremium: Boolean,
    @SerialName("auction_info") val auctionInfo: GiftAuction? = null,
    @SerialName("next_send_date") val nextSendDate: Int,
    @SerialName("user_limits") val userLimits: GiftPurchaseLimits? = null,
    @SerialName("overall_limits") val overallLimits: GiftPurchaseLimits? = null,
    @SerialName("background") val background: GiftBackground? = null,
    @SerialName("first_send_date") val firstSendDate: Int,
    @SerialName("last_send_date") val lastSendDate: Int,
    @SerialName("@type") val tdType: String = "gift"
) : TdObject

/**
 * Describes an upgraded gift that can be transferred to another owner or transferred to the TON blockchain as an NFT
 * @param id Unique identifier of the gift
 * @param regularGiftId Unique identifier of the regular gift from which the gift was upgraded; may be 0 for short period of time for old gifts from database
 * @param publisherChatId Identifier of the chat that published the gift; 0 if none
 * @param title The title of the upgraded gift
 * @param name Unique name of the upgraded gift that can be used with internalLinkTypeUpgradedGift or sendResoldGift
 * @param number Unique number of the upgraded gift among gifts upgraded from the same gift
 * @param totalUpgradedCount Total number of gifts that were upgraded from the same gift
 * @param maxUpgradedCount The maximum number of gifts that can be upgraded from the same gift
 * @param isBurned True, if the gift was used to craft another gift
 * @param isCrafted True, if the gift was crafted from other gifts
 * @param isPremium True, if the original gift could have been bought only by Telegram Premium subscribers
 * @param isThemeAvailable True, if the gift can be used to set a theme in a chat
 * @param usedThemeChatId Identifier of the chat for which the gift is used to set a theme; 0 if none or the gift isn't owned by the current user
 * @param hostId Identifier of the user or the chat to which the upgraded gift was assigned from blockchain; may be null if none or unknown
 * @param ownerId Identifier of the user or the chat that owns the upgraded gift; may be null if none or unknown
 * @param ownerAddress Address of the gift NFT owner in TON blockchain; may be empty if none. Append the address to getOption("ton_blockchain_explorer_url") to get a link with information about the address
 * @param ownerName Name of the owner for the case when owner identifier and address aren't known
 * @param giftAddress Address of the gift NFT in TON blockchain; may be empty if none. Append the address to getOption("ton_blockchain_explorer_url") to get a link with information about the address
 * @param model Model of the upgraded gift
 * @param symbol Symbol of the upgraded gift
 * @param backdrop Backdrop of the upgraded gift
 * @param originalDetails Information about the originally sent gift; may be null if unknown
 * @param colors Colors that can be set for user's name, background of empty chat photo, replies to messages and link previews; may be null if none or unknown
 * @param resaleParameters Resale parameters of the gift; may be null if resale isn't possible
 * @param canSendPurchaseOffer True, if an offer to purchase the gift can be sent using sendGiftPurchaseOffer
 * @param craftProbabilityPerMille Probability that the gift adds to the chance of successful crafting of a new gift; 0 if the gift can't be used for crafting
 * @param valueCurrency ISO 4217 currency code of the currency in which value of the gift is represented; may be empty if unavailable
 * @param valueAmount Estimated value of the gift; in the smallest units of the currency; 0 if unavailable
 * @param valueUsdAmount Estimated value of the gift in USD; in USD cents; 0 if unavailable
 */
@Serializable
data class UpgradedGift(
    @SerialName("id") val id: Long,
    @SerialName("regular_gift_id") val regularGiftId: Long,
    @SerialName("publisher_chat_id") val publisherChatId: Long,
    @SerialName("title") val title: String? = null,
    @SerialName("name") val name: String? = null,
    @SerialName("number") val number: Int,
    @SerialName("total_upgraded_count") val totalUpgradedCount: Int,
    @SerialName("max_upgraded_count") val maxUpgradedCount: Int,
    @SerialName("is_burned") val isBurned: Boolean,
    @SerialName("is_crafted") val isCrafted: Boolean,
    @SerialName("is_premium") val isPremium: Boolean,
    @SerialName("is_theme_available") val isThemeAvailable: Boolean,
    @SerialName("used_theme_chat_id") val usedThemeChatId: Long,
    @SerialName("host_id") val hostId: MessageSender? = null,
    @SerialName("owner_id") val ownerId: MessageSender? = null,
    @SerialName("owner_address") val ownerAddress: String? = null,
    @SerialName("owner_name") val ownerName: String? = null,
    @SerialName("gift_address") val giftAddress: String? = null,
    @SerialName("model") val model: UpgradedGiftModel? = null,
    @SerialName("symbol") val symbol: UpgradedGiftSymbol? = null,
    @SerialName("backdrop") val backdrop: UpgradedGiftBackdrop? = null,
    @SerialName("original_details") val originalDetails: UpgradedGiftOriginalDetails? = null,
    @SerialName("colors") val colors: UpgradedGiftColors? = null,
    @SerialName("resale_parameters") val resaleParameters: GiftResaleParameters? = null,
    @SerialName("can_send_purchase_offer") val canSendPurchaseOffer: Boolean,
    @SerialName("craft_probability_per_mille") val craftProbabilityPerMille: Int,
    @SerialName("value_currency") val valueCurrency: String? = null,
    @SerialName("value_amount") val valueAmount: Long,
    @SerialName("value_usd_amount") val valueUsdAmount: Long,
    @SerialName("@type") val tdType: String = "upgradedGift"
) : TdObject

/**
 * Contains information about value of an upgraded gift
 * @param currency ISO 4217 currency code of the currency in which the prices are represented
 * @param value Estimated value of the gift; in the smallest units of the currency
 * @param isValueAverage True, if the value is calculated as average value of similar sold gifts. Otherwise, it is based on the sale price of the gift
 * @param initialSaleDate Point in time (Unix timestamp) when the corresponding regular gift was originally purchased
 * @param initialSaleStarCount The Telegram Star amount that was paid for the gift
 * @param initialSalePrice Initial price of the gift; in the smallest units of the currency
 * @param lastSaleDate Point in time (Unix timestamp) when the upgraded gift was purchased last time; 0 if never
 * @param lastSalePrice Last purchase price of the gift; in the smallest units of the currency; 0 if the gift has never been resold
 * @param isLastSaleOnFragment True, if the last sale was completed on Fragment
 * @param minimumPrice The current minimum price of gifts upgraded from the same gift; in the smallest units of the currency; 0 if there are no such gifts
 * @param averageSalePrice The average sale price in the last month of gifts upgraded from the same gift; in the smallest units of the currency; 0 if there were no such sales
 * @param telegramListedGiftCount Number of gifts upgraded from the same gift being resold on Telegram
 * @param fragmentListedGiftCount Number of gifts upgraded from the same gift being resold on Fragment
 * @param fragmentUrl The HTTPS link to the Fragment for the gift; may be empty if there are no such gifts being sold on Fragment
 */
@Serializable
data class UpgradedGiftValueInfo(
    @SerialName("currency") val currency: String? = null,
    @SerialName("value") val value: Long,
    @SerialName("is_value_average") val isValueAverage: Boolean,
    @SerialName("initial_sale_date") val initialSaleDate: Int,
    @SerialName("initial_sale_star_count") val initialSaleStarCount: Long,
    @SerialName("initial_sale_price") val initialSalePrice: Long,
    @SerialName("last_sale_date") val lastSaleDate: Int,
    @SerialName("last_sale_price") val lastSalePrice: Long,
    @SerialName("is_last_sale_on_fragment") val isLastSaleOnFragment: Boolean,
    @SerialName("minimum_price") val minimumPrice: Long,
    @SerialName("average_sale_price") val averageSalePrice: Long,
    @SerialName("telegram_listed_gift_count") val telegramListedGiftCount: Int,
    @SerialName("fragment_listed_gift_count") val fragmentListedGiftCount: Int,
    @SerialName("fragment_url") val fragmentUrl: String? = null,
    @SerialName("@type") val tdType: String = "upgradedGiftValueInfo"
) : TdObject

/**
 * Contains result of gift upgrading
 * @param gift The upgraded gift
 * @param receivedGiftId Unique identifier of the received gift for the current user
 * @param isSaved True, if the gift is displayed on the user's or the channel's profile page
 * @param canBeTransferred True, if the gift can be transferred to another owner
