    @SerialName("can_be_called") val canBeCalled: Boolean,
    @SerialName("supports_video_calls") val supportsVideoCalls: Boolean,
    @SerialName("has_private_calls") val hasPrivateCalls: Boolean,
    @SerialName("has_private_forwards") val hasPrivateForwards: Boolean,
    @SerialName("has_restricted_voice_and_video_note_messages") val hasRestrictedVoiceAndVideoNoteMessages: Boolean,
    @SerialName("has_posted_to_profile_stories") val hasPostedToProfileStories: Boolean,
    @SerialName("has_sponsored_messages_enabled") val hasSponsoredMessagesEnabled: Boolean,
    @SerialName("need_phone_number_privacy_exception") val needPhoneNumberPrivacyException: Boolean,
    @SerialName("set_chat_background") val setChatBackground: Boolean,
    @SerialName("uses_unofficial_app") val usesUnofficialApp: Boolean,
    @SerialName("bio") val bio: FormattedText? = null,
    @SerialName("birthdate") val birthdate: Birthdate? = null,
    @SerialName("personal_chat_id") val personalChatId: Long,
    @SerialName("gift_count") val giftCount: Int,
    @SerialName("group_in_common_count") val groupInCommonCount: Int,
    @SerialName("incoming_paid_message_star_count") val incomingPaidMessageStarCount: Long,
    @SerialName("outgoing_paid_message_star_count") val outgoingPaidMessageStarCount: Long,
    @SerialName("gift_settings") val giftSettings: GiftSettings? = null,
    @SerialName("bot_verification") val botVerification: BotVerification? = null,
    @SerialName("main_profile_tab") val mainProfileTab: ProfileTab? = null,
    @SerialName("first_profile_audio") val firstProfileAudio: Audio? = null,
    @SerialName("rating") val rating: UserRating? = null,
