    @SerialName("note") val note: FormattedText? = null,
    @SerialName("business_info") val businessInfo: BusinessInfo? = null,
    @SerialName("bot_info") val botInfo: BotInfo? = null,
    @SerialName("@type") val tdType: String = "userFullInfo"
