    @SerialName("message_id") val messageId: Long,
    @SerialName("quote") val quote: TextQuote? = null,
    @SerialName("checklist_task_id") val checklistTaskId: Int,
    @SerialName("poll_option_id") val pollOptionId: String? = null,
    @SerialName("origin") val origin: MessageOrigin? = null,
    @SerialName("origin_send_date") val originSendDate: Int,
    @SerialName("content") val content: MessageContent? = null,
    @SerialName("@type") val tdType: String = "messageReplyToMessage"
) : MessageReplyTo

