/**
 * Contains basic information about a forum topic
 * @param chatId Identifier of a forum supergroup chat or a chat with a bot to which the topic belongs
 * @param forumTopicId Forum topic identifier of the topic
 * @param name Name of the topic
 * @param icon Icon of the topic
 * @param creationDate Point in time (Unix timestamp) when the topic was created
 * @param creatorId Identifier of the creator of the topic
 * @param isGeneral True, if the topic is the General topic
 * @param isOutgoing True, if the topic was created by the current user
 * @param isClosed True, if the topic is closed. If the topic is closed, then the user must have can_manage_topics administrator right in the supergroup or must be the creator of the topic to send messages there
 * @param isHidden True, if the topic is hidden above the topic list and closed; for General topic only
 * @param isNameImplicit True, if the name of the topic wasn't added explicitly
 */
@Serializable
data class ForumTopicInfo(
    @SerialName("chat_id") val chatId: Long,
    @SerialName("forum_topic_id") val forumTopicId: Int,
    @SerialName("name") val name: String? = null,
    @SerialName("icon") val icon: ForumTopicIcon? = null,
    @SerialName("creation_date") val creationDate: Int,
    @SerialName("creator_id") val creatorId: MessageSender? = null,
    @SerialName("is_general") val isGeneral: Boolean,
    @SerialName("is_outgoing") val isOutgoing: Boolean,
    @SerialName("is_closed") val isClosed: Boolean,
    @SerialName("is_hidden") val isHidden: Boolean,
    @SerialName("is_name_implicit") val isNameImplicit: Boolean,
    @SerialName("@type") val tdType: String = "forumTopicInfo"
) : TdObject

/**
 * Describes a forum topic
 * @param info Basic information about the topic
 * @param lastMessage Last message in the topic; may be null if unknown
 * @param order A parameter used to determine order of the topic in the topic list. Topics must be sorted by the order in descending order
 * @param isPinned True, if the topic is pinned in the topic list
 * @param unreadCount Number of unread messages in the topic
 * @param lastReadInboxMessageId Identifier of the last read incoming message
 * @param lastReadOutboxMessageId Identifier of the last read outgoing message
 * @param unreadMentionCount Number of unread messages with a mention/reply in the topic
 * @param unreadReactionCount Number of messages with unread reactions in the topic
 * @param unreadPollVoteCount Number of messages with unread poll votes in the topic
 * @param notificationSettings Notification settings for the topic
 * @param draftMessage A draft of a message in the topic; may be null if none
 */
@Serializable
data class ForumTopic(
    @SerialName("info") val info: ForumTopicInfo? = null,
    @SerialName("last_message") val lastMessage: Message? = null,
    @SerialName("order") val order: Long,
    @SerialName("is_pinned") val isPinned: Boolean,
    @SerialName("unread_count") val unreadCount: Int,
    @SerialName("last_read_inbox_message_id") val lastReadInboxMessageId: Long,
    @SerialName("last_read_outbox_message_id") val lastReadOutboxMessageId: Long,
    @SerialName("unread_mention_count") val unreadMentionCount: Int,
    @SerialName("unread_reaction_count") val unreadReactionCount: Int,
    @SerialName("unread_poll_vote_count") val unreadPollVoteCount: Int,
    @SerialName("notification_settings") val notificationSettings: ChatNotificationSettings? = null,
    @SerialName("draft_message") val draftMessage: DraftMessage? = null,
    @SerialName("@type") val tdType: String = "forumTopic"
) : TdObject

/**
