data class InputPassportElementErrorSourceDataField(
    @SerialName("field_name") val fieldName: String? = null,
    @SerialName("data_hash") val dataHash: String? = null,
    @SerialName("@type") val tdType: String = "inputPassportElementErrorSourceDataField"
) : InputPassportElementErrorSource

/**
