@Serializable
data class InputPassportElementErrorSourceReverseSide(
    @SerialName("file_hash") val fileHash: String? = null,
    @SerialName("@type") val tdType: String = "inputPassportElementErrorSourceReverseSide"
) : InputPassportElementErrorSource

