@Serializable
data class InputPassportElementErrorSourceFiles(
    @SerialName("file_hashes") val fileHashes: List<String>? = null,
    @SerialName("@type") val tdType: String = "inputPassportElementErrorSourceFiles"
) : InputPassportElementErrorSource

