    @SerialName("members_only") val membersOnly: Boolean,
    @SerialName("country_codes") val countryCodes: List<String>? = null,
    @SerialName("shuffle_options") val shuffleOptions: Boolean,
    @SerialName("hide_results_until_closes") val hideResultsUntilCloses: Boolean,
    @SerialName("type") val type: InputPollType? = null,
    @SerialName("open_period") val openPeriod: Int,
    @SerialName("close_date") val closeDate: Int,
    @SerialName("is_closed") val isClosed: Boolean,
    @SerialName("@type") val tdType: String = "inputMessagePoll"
) : InputMessageContent

