    @SerialName("paid_message_star_count") val paidMessageStarCount: Long,
    @SerialName("scheduled_start_date") val scheduledStartDate: Int,
    @SerialName("enabled_start_notification") val enabledStartNotification: Boolean,
    @SerialName("is_active") val isActive: Boolean,
    @SerialName("is_video_chat") val isVideoChat: Boolean,
    @SerialName("is_live_story") val isLiveStory: Boolean,
    @SerialName("is_rtmp_stream") val isRtmpStream: Boolean,
    @SerialName("is_joined") val isJoined: Boolean,
    @SerialName("need_rejoin") val needRejoin: Boolean,
    @SerialName("is_owned") val isOwned: Boolean,
    @SerialName("can_be_managed") val canBeManaged: Boolean,
    @SerialName("participant_count") val participantCount: Int,
    @SerialName("has_hidden_listeners") val hasHiddenListeners: Boolean,
    @SerialName("loaded_all_participants") val loadedAllParticipants: Boolean,
    @SerialName("message_sender_id") val messageSenderId: MessageSender? = null,
    @SerialName("recent_speakers") val recentSpeakers: List<GroupCallRecentSpeaker>? = null,
    @SerialName("is_my_video_enabled") val isMyVideoEnabled: Boolean,
    @SerialName("is_my_video_paused") val isMyVideoPaused: Boolean,
    @SerialName("can_enable_video") val canEnableVideo: Boolean,
    @SerialName("mute_new_participants") val muteNewParticipants: Boolean,
    @SerialName("can_toggle_mute_new_participants") val canToggleMuteNewParticipants: Boolean,
    @SerialName("can_send_messages") val canSendMessages: Boolean,
    @SerialName("are_messages_allowed") val areMessagesAllowed: Boolean,
    @SerialName("can_toggle_are_messages_allowed") val canToggleAreMessagesAllowed: Boolean,
    @SerialName("can_delete_messages") val canDeleteMessages: Boolean,
    @SerialName("record_duration") val recordDuration: Int,
    @SerialName("is_video_recorded") val isVideoRecorded: Boolean,
    @SerialName("duration") val duration: Int,
    @SerialName("@type") val tdType: String = "groupCall"
) : TdObject

